<p>결론부터 말하면, 타이밍보다 중요한 것은 '투자 기간'과 '투자 방법'입니다. 한 번에 목돈을 넣는 것이 아니라 분할매수로 매월 일정 금액을 나눠 투자하면 고점 매수 리스크를 크게 줄일 수 있습니다.</p>

