<p>배당수익률 5%인 배당주에 1억원을 투자하면, 연간 500만원(세전)의 배당금을 받을 수 있습니다. 월로 환산하면 약 41.7만원이며,ISA 계좌를 활용하면 세후 수익도 극대화할 수 있습니다.</p>

