<p>2026년 하반기에도 AI·반도체 슈퍼사이클은 지속될 것으로 예상됩니다. 다만, 상반기 대비 지수가 크게 올라온 만큼 변동성이 커질 수 있습니다. 핵심은 "반도체 중심의 주도 비중을 유지하면서 수익원을 추가하는 전략"입니다.</p>

